package deposit.service;

import deposit.common.*;
import deposit.repository.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.ZipFile;
import org.neo4j.graphdb.Node;

/** Applies one validated snapshot using the caller's transaction and resource-import capability. */
final class ImportSnapshotMaterializer {
    private final RequestContext c;
    private final CoreRepository repo;
    private final ResourceRepository resources;

    ImportSnapshotMaterializer(RequestContext c,CoreRepository repo,ResourceRepository resources){this.c=c;this.repo=repo;this.resources=resources;}

    Map<String,Object> apply(ExchangePackageCodec.PackageData pkg,Path archive,String namespace,Map<String,Object> classMap,Map<String,Object> objectMappings,Map<String,Object> rules){applyFormScopes(pkg.graph(),namespace,objectMappings,rules);return materialize(pkg,archive,namespace,classMap,objectMappings);}

    private void applyFormScopes(Map<String,Object> graph,String namespace,Map<String,Object> mappings,Map<String,Object> rules){
        Object raw=rules.get("_formRootSource");if(!(raw instanceof String source))return;
        Node root=repo.entity("Object",namespace,(String)mappings.get(source));if(root==null)c.fail("PLAN_STALE","Form root is no longer available");
        for(Object field:(List<?>)rules.get("_formRootDescriptors")){Node d=repo.descriptor(root,(String)field);if(d!=null)repo.remove(d,new ArrayList<>());}
        var remove=new ArrayList<org.neo4j.graphdb.Relationship>();
        try(var edges=root.getRelationships(org.neo4j.graphdb.Direction.BOTH,org.neo4j.graphdb.RelationshipType.withName("RELATED_TO"))){for(var edge:edges)for(Object scopeRaw:(List<?>)rules.get("_formRootRelationships")){var scope=ValueCodec.map(scopeRaw);boolean outgoing="outgoing".equals(scope.get("direction"));if(!(outgoing?edge.getStartNode():edge.getEndNode()).equals(root))continue;Node other=outgoing?edge.getEndNode():edge.getStartNode();if(Objects.equals(scope.get("label"),edge.getProperty("label"))&&Objects.equals(scope.get("className"),repo.objectClass(other).getProperty("name"))){remove.add(edge);break;}}}
        for(var edge:remove)repo.remove(edge,new ArrayList<>());
    }

Map<String,Object> materialize(ExchangePackageCodec.PackageData pkg,Path archive,String namespace,Map<String,Object> classMap,Map<String,Object> objectMappings){
    try(var imported=resources.beginImport(namespace,c.actorId)){
    Map<String,Object> graph=pkg.graph();Map<String,String> classes=new HashMap<>(),objects=new HashMap<>(),resourcesMap=new HashMap<>(),geometriesMap=new HashMap<>(),descriptors=new HashMap<>(),memberships=new HashMap<>(),relationships=new HashMap<>(),classRelationships=new HashMap<>(),patterns=new HashMap<>(),userTools=new HashMap<>();long createdObjects=0;
    for(Object raw:(List<?>)graph.get("classes")){var source=ValueCodec.map(raw);String sourceId=(String)source.get("id"),targetName=BaseService.name(classMap.getOrDefault(source.get("name"),(String)source.get("name")));Node target=repo.find("Class",Map.of("namespaceId",namespace,"name",targetName));
        if(target==null)target=repo.create("Class",namespace,c.actorId,Json.map("name",targetName,"position",source.get("position"),"order",source.getOrDefault("order",0L),"comment",source.getOrDefault("comment","")));
        for(Object rd:(List<?>)source.get("descriptors")){var d=ValueCodec.map(rd);String field=(String)d.get("name"),type=(String)d.get("type");Node existing=repo.declaration(target,field);if(existing==null)repo.attach("ClassDescriptor",target,c.actorId,Json.map("name",field,"type",type,"order",d.getOrDefault("order",0L),"comment",d.getOrDefault("comment","")));else if(!type.equals(existing.getProperty("type")))c.fail("IMPORT_CONFLICT","Class declaration changed after analysis");}
        classes.put(sourceId,CoreRepository.id(target));
    }
    for(Object raw:(List<?>)graph.get("resources")){var source=ValueCodec.map(raw);String sourceId=(String)source.get("id"),checksum=(String)source.get("sha256");Path staged=null;try(ZipFile zip=new ZipFile(archive.toFile())){var entry=zip.getEntry("resources/"+checksum);if(entry==null)c.fail("RESOURCE_CORRUPT","Package resource content is missing");staged=resources.files.path("staging/imports/content-"+UUID.randomUUID());Files.createDirectories(staged.getParent());try(InputStream in=zip.getInputStream(entry);OutputStream out=Files.newOutputStream(staged,StandardOpenOption.CREATE_NEW)){in.transferTo(out);}if(Files.size(staged)!=((Number)source.get("bytes")).longValue()||!checksum.equals(ResourceFiles.checksum(staged)))c.fail("RESOURCE_CORRUPT","Package resource content changed");
            String targetId=imported.create(staged,(String)source.get("filename"),(String)source.getOrDefault("mediaType","application/octet-stream"),((Number)source.get("bytes")).longValue(),checksum,c.timestamp);resourcesMap.put(sourceId,targetId);
        }catch(IOException e){throw ExceptionHandler.fail("RESOURCE_CORRUPT","Unable to materialize package resource");}finally{if(staged!=null)try{Files.deleteIfExists(staged);}catch(IOException ignored){}}}
    for(Object raw:(List<?>)graph.get("objects")){var source=ValueCodec.map(raw);String sourceId=(String)source.get("id"),classId=classes.get((String)source.get("classId"));if(classId==null)c.fail("VALIDATION_FAILED","Object Class is outside the package");Object selected=objectMappings.get(sourceId);Node object=selected instanceof String targetId?repo.entity("Object",namespace,targetId):null;if(selected instanceof String&&object==null)c.fail("PLAN_STALE","A selected matching Object is no longer available");if(object==null){object=repo.create("Object",namespace,c.actorId,Json.map("position",source.getOrDefault("position",List.of(0.0,0.0))));repo.assign(object,repo.entity("Class",namespace,classId),c.actorId);createdObjects++;}else if(!Objects.equals(CoreRepository.id(repo.objectClass(object)),classId))c.fail("PLAN_STALE","A selected matching Object changed Class");objects.put(sourceId,CoreRepository.id(object));}
    for(Object raw:(List<?>)graph.get("memberships")){var m=ValueCodec.map(raw);String objectId=objects.get(m.get("objectId"));Node object=objectId==null?null:repo.entity("Object",namespace,objectId);if(object==null)c.fail("VALIDATION_FAILED","Membership Object is outside the package");memberships.put((String)m.get("id"),CoreRepository.id(repo.membership(object)));}
    for(Object raw:(List<?>)graph.get("descriptors")){var source=ValueCodec.map(raw);String sourceObject=(String)source.get("objectId"),targetObject=objects.get(sourceObject);if(targetObject==null)c.fail("VALIDATION_FAILED","Descriptor owner is outside the package");Node object=repo.entity("Object",namespace,targetObject),clazz=repo.objectClass(object);String name=(String)source.get("name");Node declaration=repo.declaration(clazz,name);if(declaration==null)c.fail("VALIDATION_FAILED","Descriptor declaration is missing");String type=(String)declaration.getProperty("type");Object incoming=ExchangePackageCodec.decodeValue(type,source.get("value")),value=incoming;if("DResource".equals(type)&&value!=null){String mappedResource=resourcesMap.get((String)ValueCodec.map(value).get("resourceId"));if(mappedResource==null)c.fail("RESOURCE_CORRUPT","Package resource reference is missing");value=Json.map("resourceId",mappedResource);}Node descriptor=repo.descriptor(object,name);if(descriptor==null){descriptor=repo.attach("Descriptor",object,c.actorId,Json.map("name",name));repo.writeImportedValue(descriptor,type,value,c.actorId,imported);}else {boolean equal="DResource".equals(type)?ImportSemantics.resourceEquivalent(resources,incoming,repo.descriptorValue(descriptor),graph,namespace):Objects.equals(repo.descriptorValue(descriptor),value);if(!equal){c.fail("PLAN_STALE","Matched Descriptor changed after analysis");}}descriptors.put((String)source.get("id"),CoreRepository.id(descriptor));if("DGeometry".equals(type)&&source.get("geometryId") instanceof String sourceGeometry){Node geometry=new GeometryRepository(c.tx,repo).geometry(descriptor);if(geometry!=null)geometriesMap.put(sourceGeometry,CoreRepository.id(geometry));} }
    for(Object raw:(List<?>)graph.get("relationships")){var edge=ValueCodec.map(raw);Node source=repo.entity("Object",namespace,objects.get(edge.get("sourceId"))),target=repo.entity("Object",namespace,objects.get(edge.get("targetId")));if(source==null||target==null)c.fail("VALIDATION_FAILED","Relationship endpoint is outside the package");var relation=repo.relationship(source,target,(String)edge.get("label"));if(relation==null)relation=repo.createRelationship(source,target,(String)edge.get("label"),edge.containsKey("weight")?Json.map("weight",edge.get("weight")):Map.of(),c.actorId);relationships.put((String)edge.get("id"),CoreRepository.id(relation));}
    for(Object raw:(List<?>)graph.get("classRelationships")){var edge=ValueCodec.map(raw);Node source=repo.entity("Class",namespace,classes.get(edge.get("sourceId"))),target=repo.entity("Class",namespace,classes.get(edge.get("targetId")));if(source==null||target==null)c.fail("VALIDATION_FAILED","Class Relationship endpoint is outside the package");var relation=repo.relationship(source,target,(String)edge.get("label"));if(relation==null)relation=repo.createRelationship(source,target,(String)edge.get("label"),Map.of(),c.actorId);classRelationships.put((String)edge.get("id"),CoreRepository.id(relation));}
    Map<String,String> mappedNames=new HashMap<>();classMap.forEach((k,v)->mappedNames.put(k,(String)v));for(Object raw:(List<?>)graph.get("patterns")){var p=ValueCodec.map(raw);Map<String,Object> definition=ImportSemantics.mapPatternClasses(ValueCodec.map(p.get("definition")),mappedNames);Node existing=repo.find("Pattern",Map.of("namespaceId",namespace,"name",p.get("name")));if(existing==null)existing=repo.create("Pattern",namespace,c.actorId,Json.map("name",p.get("name"),"definition",Json.write(definition),"comment",p.getOrDefault("comment","")));else if(!ImportSemantics.samePatternDefinition((String)existing.getProperty("definition"),definition,ImportSemantics.namespaceSchema(repo,namespace))||!Objects.equals(existing.getProperty("comment",""),p.getOrDefault("comment","")))c.fail("IMPORT_CONFLICT","Pattern name conflicts");patterns.put((String)p.get("id"),CoreRepository.id(existing));}
    for(Object raw:(List<?>)graph.get("userTools")){var tool=ValueCodec.map(raw);Node existing=repo.find("UserTool",Map.of("namespaceId",namespace,"name",tool.get("name")));if(existing==null)existing=repo.create("UserTool",namespace,c.actorId,Json.map("name",tool.get("name"),"data",tool.get("data"),"comment",tool.getOrDefault("comment","")));else if(!Objects.equals(existing.getProperty("data"),tool.get("data")))c.fail("IMPORT_CONFLICT","User Tool name conflicts");userTools.put((String)tool.get("id"),CoreRepository.id(existing));}
    new PatternService(c).validateNamespace(namespace);var mapping=new TreeMap<String,String>();mapping.putAll(classes);mapping.putAll(objects);mapping.putAll(resourcesMap);mapping.putAll(geometriesMap);var identityMappings=Json.map("Namespace",Map.of((String)pkg.manifest().get("sourceNamespaceId"),namespace),"Class",classes,"Object",objects,"DResource",resourcesMap,"DGeometry",geometriesMap,"Descriptor",descriptors,"Membership",memberships,"Relationship",relationships,"ClassRelationship",classRelationships,"Pattern",patterns,"UserTool",userTools);return Json.map("mapping",mapping,"identityMappings",identityMappings,"resourceMapping",resourcesMap,"createdClasses",(long)classes.size(),"createdObjects",createdObjects,"createdResources",(long)resourcesMap.size(),"createdRelationships",((List<?>)graph.get("relationships")).size());
    }
}

}
